 if table=='OpBasicInfo':continue
 for unit in ['cube0','vector0','vector1']:
  selected=[r for r in rows if int(r['block_id'])<16 and r['sub_block_id']==unit]
  for key in rows[0]:
   if not key or key in ['block_id','sub_block_id']:continue
   try:values=[float(r[key]) for r in selected]
   except (ValueError,TypeError):continue
   if values:medians.setdefault(unit,{})[key]=statistics.median(values)
